const { Command } = require('../');

describe('negated option default independent of order', () => {
  test.each([
    ['negated first', (p) => p.option('--no-pepper').option('--pepper')],
    ['positive first', (p) => p.option('--pepper').option('--no-pepper')],
  ])('no implicit default when both defined (%s)', (_name, add) => {
    const program = new Command();
    add(program);
    program.parse([], { from: 'user' });
    expect(program.opts().pepper).toBeUndefined();
    expect(program.getOptionValueSource('pepper')).toBeUndefined();
  });

  test('lone negated option defaults to true', () => {
    const program = new Command();
    program.option('--no-pepper');
    program.parse([], { from: 'user' });
    expect(program.opts().pepper).toBe(true);
  });

  test('explicit default on negated option used, positive first', () => {
    const program = new Command();
    program.option('--pepper').option('--no-pepper', 'remove pepper', 'plain');
    program.parse([], { from: 'user' });
    expect(program.opts().pepper).toBe('plain');
  });

  test('explicit default on negated option used, negated first', () => {
    const program = new Command();
    program.option('--no-pepper', 'remove pepper', 'plain').option('--pepper');
    program.parse([], { from: 'user' });
    expect(program.opts().pepper).toBe('plain');
  });

  test.each([
    ['--pepper', true],
    ['--no-pepper', false],
  ])('flag %s still works', (flag, expected) => {
    const program = new Command();
    program.option('--no-pepper').option('--pepper');
    program.parse([flag], { from: 'user' });
    expect(program.opts().pepper).toBe(expected);
  });
});
